package schema

import (
	"encoding/json"
	"fmt"
	"path"
	"regexp"
	"sort"
	"strings"
	"sync"

	"howett.net/plist"
)

// Platforms with payload editors.
const (
	PlatformIOS   = "ios"   // iPhone, iPad (Mobile Device Configuration Profiles)
	PlatformMacOS = "macos" // Mac (Computer Configuration Profiles)
)

// PayloadDef is a built-in editor for one payload type on one platform
// (internal/schema/payloads/<platform>/<id>.json, generated by cmd/profile-schemas
// from Apple's device-management repository for the payloads Jamf Pro offers). Besides the
// schema keywords the file carries header fields:
//
//	__id           the editor's id (the file name): usually the PayloadType, but several
//	               editors can produce one type, e.g. com.apple.MCX(EnergySaver)
//	__payloadtype  the PayloadType it produces, e.g. com.apple.applicationaccess
//	__platform     ios or macos
//	__category     the group it is listed under in the payload picker
//	__order        sort order inside the category
//	__multiple     true when a profile may hold several (Wi-Fi, VPN, certificates, …)
//	__channels     macOS: "device" and/or "user" (computer- or user-level profiles)
//	__supervised   the whole payload needs supervision
//	__requires     other requirements (Automated Device Enrollment, user-approved MDM)
//	__os           the first OS version that supports it
//	__deprecated   the OS version Apple deprecated it in
//	__jamf         the Jamf Pro payload it corresponds to, when the name differs
type PayloadDef struct {
	Type        string   `json:"type"` // editor id
	PayloadType string   `json:"payload_type"`
	Platform    string   `json:"platform"`
	Title       string   `json:"title"`
	Description string   `json:"description"`
	Category    string   `json:"category"`
	Multiple    bool     `json:"multiple"`
	Order       int      `json:"order"`
	Channels    []string `json:"channels,omitempty"`
	Supervised  bool     `json:"supervised,omitempty"`
	Requires    []string `json:"requires,omitempty"`
	OS          string   `json:"os,omitempty"`
	Deprecated  string   `json:"deprecated,omitempty"`
	Jamf        string   `json:"jamf,omitempty"`
	Schema      *Schema  `json:"-"`
	Raw         []byte   `json:"-"`
}

// MobilePayload is the iOS payload editor (kept for the mobile API).
type MobilePayload = PayloadDef

type payloadHeader struct {
	ID          string   `json:"__id"`
	PayloadType string   `json:"__payloadtype"`
	Platform    string   `json:"__platform"`
	Category    string   `json:"__category"`
	Multiple    bool     `json:"__multiple"`
	Order       int      `json:"__order"`
	Channels    []string `json:"__channels"`
	Supervised  bool     `json:"__supervised"`
	Requires    []string `json:"__requires"`
	OS          string   `json:"__os"`
	Deprecated  string   `json:"__deprecated"`
	Jamf        string   `json:"__jamf"`
}

var (
	payloadsOnce sync.Once
	payloadsBy   map[string][]PayloadDef
)

func loadPayloads() {
	payloadsBy = map[string][]PayloadDef{}
	for _, plat := range []string{PlatformIOS, PlatformMacOS} {
		dir := path.Join("payloads", plat)
		entries, _ := builtinFS.ReadDir(dir)
		var out []PayloadDef
		for _, e := range entries {
			raw, err := builtinFS.ReadFile(path.Join(dir, e.Name()))
			if err != nil {
				continue
			}
			s, err := Parse(raw)
			if err != nil {
				panic("invalid payload schema " + plat + "/" + e.Name() + ": " + err.Error())
			}
			var h payloadHeader
			json.Unmarshal(raw, &h)
			if h.ID == "" {
				h.ID = h.PayloadType
			}
			if h.PayloadType == "" || h.ID+".json" != e.Name() {
				panic("payload schema " + plat + "/" + e.Name() + ": __id must match the file name")
			}
			out = append(out, PayloadDef{Type: h.ID, PayloadType: h.PayloadType, Platform: plat, Title: s.Title, Description: s.Description, Category: h.Category,
				Multiple: h.Multiple, Order: h.Order, Channels: h.Channels, Supervised: h.Supervised, Requires: h.Requires, OS: h.OS,
				Deprecated: h.Deprecated, Jamf: h.Jamf, Schema: s, Raw: raw})
		}
		sort.SliceStable(out, func(i, j int) bool {
			if ci, cj := categoryRank(out[i].Category), categoryRank(out[j].Category); ci != cj {
				return ci < cj
			}
			if out[i].Order != out[j].Order {
				return out[i].Order < out[j].Order
			}
			return out[i].Title < out[j].Title
		})
		payloadsBy[plat] = out
	}
}

// Payloads returns the payload editors for a platform, by category then order.
func Payloads(platform string) []PayloadDef {
	payloadsOnce.Do(loadPayloads)
	return payloadsBy[platform]
}

// PayloadByType finds a payload editor.
func PayloadByType(platform, t string) (PayloadDef, bool) {
	for _, p := range Payloads(platform) {
		if p.Type == t {
			return p, true
		}
	}
	return PayloadDef{}, false
}

// MobilePayloads returns the iOS payload editors.
func MobilePayloads() []PayloadDef { return Payloads(PlatformIOS) }

// MobilePayloadByType finds an iOS payload editor.
func MobilePayloadByType(t string) (PayloadDef, bool) { return PayloadByType(PlatformIOS, t) }

// PayloadValues is one payload in a profile: its editor id, its PayloadUUID (set by the editor
// so other payloads can reference it, e.g. a Wi-Fi network's certificate) and the form values.
type PayloadValues struct {
	Type   string         `json:"type"`
	UUID   string         `json:"uuid,omitempty"`
	Values map[string]any `json:"values"`
}

// PayloadProfileInput describes a configuration profile built from payload editors.
type PayloadProfileInput struct {
	Platform     string
	Identifier   string
	DisplayName  string
	Description  string
	Organization string
	// Level (macOS): "device" (computer level, the default) or "user".
	Level    string
	Payloads []PayloadValues
}

// MobileProfileInput describes an iOS profile (Platform is ios).
type MobileProfileInput = PayloadProfileInput

// PayloadErrors are validation errors for one payload (by index in the profile).
type PayloadErrors struct {
	Index  int          `json:"index"`
	Errors []FieldError `json:"errors"`
}

var uuidRe = regexp.MustCompile(`^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$`)

// BuildMobileProfile builds an iOS profile.
func BuildMobileProfile(in MobileProfileInput) ([]byte, []PayloadErrors, error) {
	in.Platform = PlatformIOS
	return BuildPayloadProfile(in)
}

// BuildPayloadProfile validates every payload against its editor and renders the
// configuration profile. UUIDs come from the editor or derive from the identifier and
// position, so an unchanged profile renders identically.
func BuildPayloadProfile(in PayloadProfileInput) ([]byte, []PayloadErrors, error) {
	if len(in.Payloads) == 0 {
		return nil, nil, fmt.Errorf("add at least one payload")
	}
	if in.Platform == "" {
		in.Platform = PlatformIOS
	}
	level := "device"
	if in.Platform == PlatformMacOS && in.Level == "user" {
		level = "user"
	}
	// PayloadUUIDs first, so references between payloads can be checked.
	uuids := make([]string, len(in.Payloads))
	byUUID := map[string]string{}
	for i, pv := range in.Payloads {
		id := fmt.Sprintf("%s.%s.%d", in.Identifier, strings.TrimPrefix(pv.Type, "com.apple."), i+1)
		u := strings.ToUpper(strings.TrimSpace(pv.UUID))
		if !uuidRe.MatchString(u) || byUUID[u] != "" {
			u = stableUUID(id)
		}
		uuids[i] = u
		byUUID[u] = pv.Type
		if def, ok := PayloadByType(in.Platform, pv.Type); ok {
			byUUID[u] = def.PayloadType
		}
	}
	var content []any
	var perrs []PayloadErrors
	seen := map[string]bool{}
	for i, pv := range in.Payloads {
		def, ok := PayloadByType(in.Platform, pv.Type)
		if !ok {
			return nil, nil, fmt.Errorf("unknown payload type %q", pv.Type)
		}
		if seen[pv.Type] && !def.Multiple {
			return nil, nil, fmt.Errorf("a profile can hold only one %s payload", def.Title)
		}
		seen[pv.Type] = true
		if in.Platform == PlatformMacOS && len(def.Channels) > 0 && !contains(def.Channels, level) {
			return nil, nil, fmt.Errorf("%s can't be used in a %s-level profile", def.Title, map[string]string{"device": "computer", "user": "user"}[level])
		}
		vals, errs := def.Schema.Validate(pv.Values)
		errs = append(errs, checkRefs(&def.Schema.Node, vals, "", byUUID, uuids[i])...)
		if len(errs) > 0 {
			perrs = append(perrs, PayloadErrors{Index: i, Errors: errs})
			continue
		}
		ptype := def.PayloadType
		vals, ptype = transformPayload(pv.Type, ptype, vals)
		id := fmt.Sprintf("%s.%s.%d", in.Identifier, strings.TrimPrefix(ptype, "com.apple."), i+1)
		p := map[string]any{}
		for k, v := range vals {
			p[k] = v
		}
		p["PayloadType"] = ptype
		p["PayloadVersion"] = 1
		p["PayloadIdentifier"] = id
		p["PayloadUUID"] = uuids[i]
		if _, ok := p["PayloadDisplayName"]; !ok {
			p["PayloadDisplayName"] = def.Title
		}
		content = append(content, p)
	}
	if len(perrs) > 0 {
		return nil, perrs, nil
	}
	scope := "System"
	if level == "user" {
		scope = "User"
	}
	top := map[string]any{
		"PayloadType": "Configuration", "PayloadVersion": 1, "PayloadIdentifier": in.Identifier,
		"PayloadUUID": stableUUID(in.Identifier), "PayloadDisplayName": in.DisplayName, "PayloadDescription": in.Description,
		"PayloadOrganization": in.Organization, "PayloadScope": scope, "PayloadRemovalDisallowed": true,
		"PayloadContent": content,
	}
	out, err := plist.MarshalIndent(top, plist.XMLFormat, "\t")
	return out, nil, err
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// checkRefs makes sure payload references (format "payload-ref") point at a payload of an
// allowed type in the same profile.
func checkRefs(n *Node, v any, path string, byUUID map[string]string, self string) []FieldError {
	var errs []FieldError
	switch t := v.(type) {
	case map[string]any:
		for k, x := range t {
			c := n.Properties[k]
			if c == nil {
				c = n.additional
			}
			if c != nil {
				errs = append(errs, checkRefs(c, x, join(path, k), byUUID, self)...)
			}
		}
	case []any:
		if n.Items != nil {
			for i, x := range t {
				errs = append(errs, checkRefs(n.Items, x, fmt.Sprintf("%s[%d]", path, i), byUUID, self)...)
			}
		}
	case string:
		if n.Format != "payload-ref" {
			return nil
		}
		typ, ok := byUUID[strings.ToUpper(t)]
		switch {
		case !ok || strings.EqualFold(t, self):
			errs = append(errs, FieldError{path, "must point to a payload in this profile"})
		case len(n.RefTypes) > 0 && !contains(n.RefTypes, typ):
			errs = append(errs, FieldError{path, "points to a payload of the wrong kind"})
		}
	}
	return errs
}

// transformPayload reshapes form values where Apple's format can't be expressed
// in the form engine directly; it can also pick the PayloadType (Ethernet interfaces).
func transformPayload(id, ptype string, v map[string]any) (map[string]any, string) {
	switch id {
	case "com.apple.globalethernet.managed":
		// One Ethernet (802.1X) editor for Apple's per-interface payload types.
		iface, _ := v[InterfaceKey].(string)
		delete(v, InterfaceKey)
		e, ok := ethernetTypes[iface]
		if !ok {
			e = ethernetTypes["any"]
		}
		ptype, v["Interface"] = e[0], e[1]
	case "com.apple.homescreenlayout":
		// The form edits Pages as [{"Items": [...]}, …]; Apple wants an array of arrays.
		if pages, ok := v["Pages"].([]any); ok {
			out := make([]any, 0, len(pages))
			for _, pg := range pages {
				m, _ := pg.(map[string]any)
				items, _ := m["Items"].([]any)
				if items == nil {
					items = []any{}
				}
				out = append(out, items)
			}
			v["Pages"] = out
		}
	}
	return v, ptype
}

// InterfaceKey is the Ethernet editor's synthetic "which interface" setting.
const InterfaceKey = "__interface"

var ethernetTypes = map[string][2]string{
	"any":           {"com.apple.globalethernet.managed", "GlobalEthernet"},
	"first-active":  {"com.apple.firstactiveethernet.managed", "FirstActiveEthernet"},
	"second-active": {"com.apple.secondactiveethernet.managed", "SecondActiveEthernet"},
	"third-active":  {"com.apple.thirdactiveethernet.managed", "ThirdActiveEthernet"},
	"first":         {"com.apple.firstethernet.managed", "FirstEthernet"},
	"second":        {"com.apple.secondethernet.managed", "SecondEthernet"},
	"third":         {"com.apple.thirdethernet.managed", "ThirdEthernet"},
}

// categories orders the payload picker (both platforms); unknown categories go last.
var categories = []string{"General", "Security", "Restrictions", "Network", "Certificates", "Accounts", "Single Sign-On", "Apps and Home Screen",
	"System", "Users and Login", "Education", "Apple TV"}

func categoryRank(c string) int {
	for i, x := range categories {
		if x == c {
			return i
		}
	}
	return len(categories)
}

// IsSecret reports whether the field at path (keys, "[]" for list items) is hidden from viewers.
func (p PayloadDef) IsSecret(path []string) bool {
	n := &p.Schema.Node
	for _, k := range path {
		switch {
		case k == "[]" && n.Items != nil:
			n = n.Items
		case n.Properties[k] != nil:
			n = n.Properties[k]
		case n.additional != nil:
			n = n.additional
		default:
			return false
		}
	}
	return n.Secret
}
